// 1. Validate Inputs and Handle Disable
int input_valid = 1;

if (!pg_input.enable) {
    pg_state.mode = PG_INIT;
    pg_state.rejects = 0;
    pg_state.initialized = 0;
    pg_output.mode = PG_INIT;
    pg_output.rejects = 0;
    pg_output.cosine = 0.0;
    pg_output.rate_norm_t_s = 0.0;
    pg_output.rate_t_s.x = 0.0;
    pg_output.rate_t_s.y = 0.0;
    pg_output.rate_t_s.z = 0.0;
    pg_output.accepted_field_t.x = 0.0;
    pg_output.accepted_field_t.y = 0.0;
    pg_output.accepted_field_t.z = 0.0;
    return;
}

// Check Config Ranges
if (pg_config.minimum_cosine < -1.0 || pg_config.minimum_cosine > 1.0 ||
    pg_config.max_rejects < 1 || pg_config.max_rejects > 20) {
    input_valid = 0;
}

// Check Field Validity (Non-NULL, Finite, Non-Degenerate)
if (pg_input.field_body_t == NULL) {
    input_valid = 0;
} else {
    double fx = pg_input.field_body_t->x;
    double fy = pg_input.field_body_t->y;
    double fz = pg_input.field_body_t->z;
    if (!isfinite(fx) || !isfinite(fy) || !isfinite(fz)) {
        input_valid = 0;
    } else {
        double norm_sq = fx * fx + fy * fy + fz * fz;
        if (norm_sq < FLT64_ZERO * FLT64_ZERO) { // Non-degenerate check
            input_valid = 0;
        }
    }
}

// Check DT
if (!isfinite(pg_input.dt_s) || pg_input.dt_s <= 0.0) {
    input_valid = 0;
}

// 2. Handle Invalid Input or Existing Fault State
if (!input_valid || pg_state.mode == PG_FAULT) {
    pg_state.mode = PG_FAULT;
    pg_output.mode = PG_FAULT;
    pg_output.rejects = pg_state.rejects;
    pg_output.cosine = 0.0;
    pg_output.rate_norm_t_s = 0.0;
    pg_output.rate_t_s.x = 0.0;
    pg_output.rate_t_s.y = 0.0;
    pg_output.rate_t_s.z = 0.0;
    pg_output.accepted_field_t = pg_state.previous;
    return;
}

// 3. Initialization Phase (First Valid Sample)
if (!pg_state.initialized) {
    pg_state.previous = *pg_input.field_body_t;
    pg_state.initialized = 1;
    pg_state.rejects = 0;

    pg_output.mode = PG_RUN;
    pg_output.rejects = 0;
    pg_output.cosine = 0.0;
    pg_output.rate_norm_t_s = 0.0;
    pg_output.rate_t_s.x = 0.0;
    pg_output.rate_t_s.y = 0.0;
    pg_output.rate_t_s.z = 0.0;
    pg_output.accepted_field_t = pg_state.previous;
    return;
}

// 4. Calculate Cosine
adcs_vec3_t prev_normed, curr_normed;
double norm_prev = sqrt(pg_state.previous.x * pg_state.previous.x +
                        pg_state.previous.y * pg_state.previous.y +
                        pg_state.previous.z * pg_state.previous.z);
double norm_curr = sqrt(pg_input.field_body_t->x * pg_input.field_body_t->x +
                        pg_input.field_body_t->y * pg_input.field_body_t->y +
                        pg_input.field_body_t->z * pg_input.field_body_t->z);

prev_normed.x = pg_state.previous.x / norm_prev;
prev_normed.y = pg_state.previous.y / norm_prev;
prev_normed.z = pg_state.previous.z / norm_prev;

curr_normed.x = pg_input.field_body_t->x / norm_curr;
curr_normed.y = pg_input.field_body_t->y / norm_curr;
curr_normed.z = pg_input.field_body_t->z / norm_curr;

double cosine = prev_normed.x * curr_normed.x + 
                prev_normed.y * curr_normed.y + 
                prev_normed.z * curr_normed.z;

if (cosine > 1.0) cosine = 1.0;
if (cosine < -1.0) cosine = -1.0;

// 5. Continuity Decision
if (cosine >= pg_config.minimum_cosine) {
    // Accept
    adcs_vec3_t diff = adcs_vec3_sub(pg_input.field_body_t, &pg_state.previous);
    pg_output.rate_t_s = adcs_vec3_scale(&diff, 1.0 / pg_input.dt_s);
    pg_output.rate_norm_t_s = adcs_vec3_norm(&pg_output.rate_t_s);

    pg_state.previous = *pg_input.field_body_t;
    pg_state.rejects = 0;

    pg_output.mode = PG_RUN;
    pg_output.rejects = 0;
    pg_output.cosine = cosine;
    pg_output.accepted_field_t = pg_state.previous;
} else {
    // Reject
    if (pg_state.rejects < pg_config.max_rejects) {
        pg_state.rejects++;
        pg_output.mode = PG_REJECT;
        pg_output.rejects = pg_state.rejects;
        pg_output.cosine = cosine;
        pg_output.rate_norm_t_s = 0.0;
        pg_output.rate_t_s.x = 0.0;
        pg_output.rate_t_s.y = 0.0;
        pg_output.rate_t_s.z = 0.0;
        pg_output.accepted_field_t = pg_state.previous;
    } else {
        // Reached Max Rejects -> Latch Fault
        pg_output.mode = PG_FAULT;
        pg_output.rejects = pg_state.rejects;
        pg_output.cosine = cosine;
        pg_output.rate_norm_t_s = 0.0;
        pg_output.rate_t_s.x = 0.0;
        pg_output.rate_t_s.y = 0.0;
        pg_output.rate_t_s.z = 0.0;
        pg_output.accepted_field_t = pg_state.previous;

        pg_state.mode = PG_FAULT;
    }
}

