    if (pg_config.minimum_cosine < -1.0 || pg_config.minimum_cosine > 1.0) {
        goto fault_latch;
    }

    // 3. If no history initialized, store current field as previous
    if (!pg_state.initialized) {
        pg_state.previous = *pg_input.field_body_t;
        pg_state.initialized = 1;

        pg_output.mode = PG_RUN;
        pg_output.rejects = 0;
        pg_output.cosine = 0.0;
        pg_output.rate_norm_t_s = 0.0;
        pg_output.rate_t_s.x = 0.0;
        pg_output.rate_t_s.y = 0.0;
        pg_output.rate_t_s.z = 0.0;
        pg_output.accepted_field_t = pg_state.previous;
        return;
    }

    // 4. Calculate cosine of angle between current and previous fields
    adcs_vec3_t prev_norm, curr_norm;
    double norm_prev, norm_curr;

    // Normalize previous field
    norm_prev = adcs_vec3_norm(&pg_state.previous);
    if (norm_prev <= ADCS_EPS_NORM) {
        goto fault_latch;
    }
    prev_norm = (adcs_vec3_t){pg_state.previous.x / norm_prev, pg_state.previous.y / norm_prev, pg_state.previous.z / norm_prev};

    // Normalize current field
    norm_curr = adcs_vec3_norm(pg_input.field_body_t);
    if (norm_curr <= ADCS_EPS_NORM) {
        goto fault_latch;
    }
    curr_norm = (adcs_vec3_t){pg_input.field_body_t->x / norm_curr, pg_input.field_body_t->y / norm_curr, pg_input.field_body_t->z / norm_curr};

    double cosine = adcs_vec3_dot(&prev_norm, &curr_norm);

    // Clamp cosine to [-1, 1]
    if (cosine > 1.0) cosine = 1.0;
    if (cosine < -1.0) cosine = -1.0;

    pg_output.cosine = cosine;

    // 5. Check continuity against minimum_cosine
    if (cosine >= pg_config.minimum_cosine) {
        // Accepted sample
        adcs_vec3_t delta = adcs_vec3_sub(pg_input.field_body_t, &pg_state.previous);
        adcs_vec3_t rate = adcs_vec3_scale(&delta, 1.0 / pg_input.dt_s);

        pg_output.mode = PG_RUN;
        pg_output.rejects = 0;
        pg_output.rate_t_s = rate;
        pg_output.rate_norm_t_s = adcs_vec3_norm(&rate);
        pg_output.accepted_field_t = *pg_input.field_body_t;

        // Update history
        pg_state.previous = *pg_input.field_body_t;
    } else {
        // Rejected sample
        if (pg_state.rejects < pg_config.max_rejects) {
            pg_output.mode = PG_REJECT;
            pg_state.rejects++;
            pg_output.rejects = pg_state.rejects;
            pg_output.rate_norm_t_s = 0.0;
            pg_output.rate_t_s.x = 0.0;
            pg_output.rate_t_s.y = 0.0;
            pg_output.rate_t_s.z = 0.0;
            pg_output.accepted_field_t = pg_state.previous;

            // Check if this rejection reached the limit
            if (pg_state.rejects >= pg_config.max_rejects) {
                pg_output.mode = PG_FAULT;
            }
        } else {
            // Already at max rejects, stay in fault
            goto fault_latch;
        }
    }
    return;

