    adcs_vec3_t diff = adcs_vec3_sub(&current, &pg_state.previous);
    adcs_vec3_t rate = adcs_vec3_scale(&diff, 1.0 / pg_input.dt_s);

    pg_state.previous = current;
    pg_state.rejects = 0;
    pg_state.mode = PG_RUN;

    pg_output.mode = PG_RUN;
    pg_output.rejects = 0;
    pg_output.rate_t_s = rate;
    pg_output.rate_norm_t_s = adcs_vec3_norm(&rate);
    pg_output.accepted_field_t = current;
} 
// 8. Rejection Check
else {
    pg_state.rejects++;

    if (pg_state.rejects >= pg_config.max_rejects) {
        // Trigger Fault
        pg_state.mode = PG_FAULT;
        pg_output.mode = PG_FAULT;
        pg_output.rejects = pg_state.rejects;
        pg_output.rate_norm_t_s = 0.0;
        pg_output.rate_t_s.x = 0.0;
        pg_output.rate_t_s.y = 0.0;
        pg_output.rate_t_s.z = 0.0;
        // History preserved
    } else {
        // Reject
        pg_state.mode = PG_REJECT;
        pg_output.mode = PG_REJECT;
        pg_output.rejects = pg_state.rejects;
        pg_output.rate_norm_t_s = 0.0;
        pg_output.rate_t_s.x = 0.0;
        pg_output.rate_t_s.y = 0.0;
        pg_output.rate_t_s.z = 0.0;
        // History preserved
    }
}
